#!/usr/bin/env node
// bundle.js — turn a shot's frame list into queue jobs: bundles of N lines, each a job that renders its lines through the
// desk's own frame tool, skips frames already in the cache, and puts the new ones in. The laptop becomes the desk; any
// worker with the renderer and the data renders bundles.
//
//   node bundle.js FRAMES.tsv --scene SCENE.json --fov F --size WxH --settings GO.sh --bin BIN [--libs a,b] [--n 48] [--frame-tool PATH] [--out DIR] [--needs cloudy|clear|any]
//     -> DIR/<shot>_b000.sh … (one job per bundle) and DIR/<shot>_assemble.sh (collects PNGs from the cache into the shot folder and makes the clip)
//
// A job: for each of its lines, identity = manifest.js hash; cache get → copy; else render the line with the frame tool
// (w23/frame.sh TSV SCENE FOV W H) and cache put. frame.sh writes PNGs at column 1's path with .ppm→.png; the job rewrites
// column 1 into its own temp folder so nothing writes into the shot folder but the assemble step.
"use strict";
const fs = require("fs"), path = require("path"), { execFileSync } = require("child_process");
const REST = process.argv.slice(2), opt = (k, d) => { const i = REST.indexOf("--" + k); return i >= 0 ? REST[i + 1] : d; };
const TSV = REST[0]; if (!TSV) { console.log(fs.readFileSync(__filename, "utf8").split("\n").slice(1, 12).join("\n")); process.exit(2); }
const N = +opt("n", 48), shot = opt("shot", path.basename(path.dirname(path.resolve(TSV)))), out = path.resolve(opt("out", path.join(path.dirname(TSV), "jobs"))); fs.mkdirSync(out, { recursive: true });
const MAN = path.join(__dirname, "..", "manifest.js"), FT = opt("frame-tool", "$ST/w23/frame.sh"), needs = opt("needs", /CLOUDS_FILE/.test(fs.readFileSync(TSV, "utf8")) ? "cloudy" : "clear");
const envArgs = ["--settings", opt("settings"), "--bin", opt("bin"), "--scene", opt("scene"), "--size", opt("size"), "--fov", opt("fov"), ...(opt("libs") ? ["--libs", opt("libs")] : [])];
execFileSync("node", [MAN, "hash", TSV, ...envArgs], { stdio: "inherit" });
const ids = fs.readFileSync(TSV.replace(/\.tsv$/, "") + ".hash.tsv", "utf8").trim().split("\n").slice(1).map(l => l.split("\t"));
const lines = fs.readFileSync(TSV, "utf8").split("\n").filter(Boolean), jobs = [];
for (let b = 0; b * N < lines.length; b++) {
  const sl = lines.slice(b * N, (b + 1) * N), name = `${shot}_b${String(b).padStart(3, "0")}`, f = path.join(out, name + ".sh");
  const tsvText = sl.map((l, k) => { const c = l.split("\t"); c[0] = `$T/f_${String(b * N + k).padStart(5, "0")}.ppm`; return c.join("\t"); }).join("\n");
  fs.writeFileSync(f, `#!/bin/bash
# bundle ${b} of ${shot}: lines ${b * N}..${b * N + sl.length - 1} (generated by bundle.js; re-runnable)
set -u; ST=\${ST:?set ST to the stonehenge root}; T=$(mktemp -d "\${RENDER_TMP:-$HOME/.cache/render-bundles}/${name}.XXXX")
MAN=${MAN}; CACHE_GET() { node $MAN cache get "$1"; }; CACHE_PUT() { node $MAN cache put "$1" "$2" > /dev/null; }
ids=(${ids.slice(b * N, (b + 1) * N).map(x => x[1]).join(" ")})
: > $T/todo.tsv; k=0
while IFS= read -r line; do i=$((${b * N} + k)); h=\${ids[$k]}; p=$(CACHE_GET $h) && cp "$p" $T/f_$(printf %05d $i).png || printf '%s\\n' "$line" >> $T/todo.tsv; k=$((k+1)); done <<'TSV'
${tsvText}
TSV
if [ -s $T/todo.tsv ]; then sed -i "s|\\$T|$T|g" $T/todo.tsv; ${FT} $T/todo.tsv ${opt("scene")} ${opt("fov")} ${opt("size").replace("x", " ")} || exit 1
  k=0; while IFS= read -r line; do i=$((${b * N} + k)); f=$T/f_$(printf %05d $i).png; [ -s $f ] && CACHE_PUT \${ids[$k]} $f; k=$((k+1)); done < <(printf '%s\\n' "${sl.map((l, k) => b * N + k).join("\\n")}" | sed 's/^/x /')
fi
n=$(ls $T/f_*.png 2>/dev/null | wc -l); echo "${name}: $n/${sl.length} frames (cache + render)"; [ $n = ${sl.length} ] || exit 2
echo $T > ${out}/${name}.where
`, { mode: 0o755 }); jobs.push(f);
}
fs.writeFileSync(path.join(out, `${shot}_assemble.sh`), `#!/bin/bash
# assemble ${shot}: every frame from the cache into the shot folder, then the clip (run after all bundles are done)
set -u; D=\${1:?output folder}; mkdir -p $D; MAN=${MAN}; miss=0
while IFS=$'\\t' read -r i h rest; do [ "$i" = i ] && continue; p=$(node $MAN cache get $h) || { echo "missing frame $i ($h)"; miss=$((miss+1)); continue; }; cp "$p" $D/f_$(printf %05d $i).png; done < ${TSV.replace(/\.tsv$/, "") + ".hash.tsv"}
[ $miss = 0 ] || { echo "$miss frames missing — run their bundles"; exit 2; }
ffmpeg -loglevel error -y -framerate 24 -i $D/f_%05d.png -c:v libx264 -crf 18 -pix_fmt yuv420p $D/../${shot}.mp4.tmp.mp4 && mv $D/../${shot}.mp4.tmp.mp4 $D/../${shot}.mp4 && echo "clip $D/../${shot}.mp4"
`, { mode: 0o755 });
console.log(`${jobs.length} bundle job(s) of ≤${N} lines in ${out} (needs=${needs}); queue them with: for j in ${out}/${shot}_b*.sh; do q add $j --needs ${needs}; done; then ${out}/${shot}_assemble.sh OUTDIR/${shot}`);
